package logfan

import (
	"context"
	"errors"
	"log/slog"
	"sync"
)

// Ring is an in-memory ring-buffer slog.Handler that keeps the most
// recent records up to its configured capacity.
type Ring struct {
	mu       sync.RWMutex
	capacity int
	buf      []slog.Record
	start    int
	count    int
}

// NewRing creates a *Ring with the given capacity.
// Returns an error if capacity <= 0.
func NewRing(capacity int) (*Ring, error) {
	if capacity <= 0 {
		return nil, errors.New("logfan: ring capacity must be positive")
	}
	return &Ring{
		capacity: capacity,
		buf:      make([]slog.Record, capacity),
	}, nil
}

// Enabled reports whether the handler handles records at the given level.
// Ring accepts all levels.
func (r *Ring) Enabled(_ context.Context, _ slog.Level) bool {
	return true
}

// Handle handles the slog.Record by storing it in the ring buffer.
func (r *Ring) Handle(_ context.Context, rec slog.Record) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	idx := (r.start + r.count) % r.capacity
	r.buf[idx] = rec.Clone()
	if r.count == r.capacity {
		r.start = (r.start + 1) % r.capacity
	} else {
		r.count++
	}
	return nil
}

// WithAttrs returns a new Handler whose attributes consist of
// the receiver's attributes followed by attrs.
func (r *Ring) WithAttrs(attrs []slog.Attr) slog.Handler {
	// Ring is a simple handler that doesn't carry its own attributes.
	// Wrap in a handler that prepends the given attrs, then stores into r.
	return &attachedRing{parent: r, attrs: attrs}
}

// WithGroup returns a new Handler that starts a group with the given name.
func (r *Ring) WithGroup(name string) slog.Handler {
	return &groupedRing{parent: r, group: name}
}

// Records returns the buffered records, oldest first.
// The returned slice is a copy — mutating it does not affect the ring.
func (r *Ring) Records() []slog.Record {
	r.mu.RLock()
	defer r.mu.RUnlock()

	out := make([]slog.Record, r.count)
	for i := 0; i < r.count; i++ {
		idx := (r.start + i) % r.capacity
		out[i] = r.buf[idx].Clone()
	}
	return out
}

// attachedRing prepends attributes before storing records into the parent Ring.
type attachedRing struct {
	parent *Ring
	attrs  []slog.Attr
}

func (h *attachedRing) Enabled(ctx context.Context, level slog.Level) bool {
	return h.parent.Enabled(ctx, level)
}

func (h *attachedRing) Handle(ctx context.Context, rec slog.Record) error {
	rec.AddAttrs(h.attrs...)
	return h.parent.Handle(ctx, rec)
}

func (h *attachedRing) WithAttrs(attrs []slog.Attr) slog.Handler {
	// Merge new attrs after existing ones.
	merged := make([]slog.Attr, 0, len(h.attrs)+len(attrs))
	merged = append(merged, h.attrs...)
	merged = append(merged, attrs...)
	return &attachedRing{parent: h.parent, attrs: merged}
}

func (h *attachedRing) WithGroup(name string) slog.Handler {
	return &groupedRing{parent: h.parent, group: name, baseAttrs: h.attrs}
}

// groupedRing wraps records in a group before storing into the parent Ring.
type groupedRing struct {
	parent    *Ring
	group     string
	baseAttrs []slog.Attr
}

func (h *groupedRing) Enabled(ctx context.Context, level slog.Level) bool {
	return h.parent.Enabled(ctx, level)
}

func (h *groupedRing) Handle(ctx context.Context, rec slog.Record) error {
	// slog.Record does not have a direct method to add a group after creation.
	// We use an intermediate handler approach: we store the record with
	// a group prefix by leveraging slog's built-in grouping support.
	// However, Record only supports AddAttrs, not AddGroup.
	// The standard approach is to use a wrapper handler that prepends
	// the group by capturing attrs via an slog.GroupValue.
	//
	// Since slog.Record stores attrs sequentially, we insert the group
	// by wrapping in a handler that adds the group on the way in.
	// This is best done by creating a temporary handler chain.
	return h.HandleWithGroup(ctx, rec)
}

// HandleWithGroup handles the record by wrapping it in the group.
func (h *groupedRing) HandleWithGroup(ctx context.Context, rec slog.Record) error {
	// Collect existing attrs from the record.
	var attrs []slog.Attr
	rec.Attrs(func(a slog.Attr) bool {
		attrs = append(attrs, a)
		return true
	})

	// Create a new record without attrs
	newRec := slog.NewRecord(rec.Time, rec.Level, rec.Message, rec.PC)

	// Add the group with the collected attrs
	newRec.AddAttrs(slog.Group(h.group, h.baseAttrs...))
	newRec.AddAttrs(attrs...)

	return h.parent.Handle(ctx, newRec)
}

func (h *groupedRing) WithAttrs(attrs []slog.Attr) slog.Handler {
	merged := make([]slog.Attr, 0, len(h.baseAttrs)+len(attrs))
	merged = append(merged, h.baseAttrs...)
	merged = append(merged, attrs...)
	return &groupedRing{parent: h.parent, group: h.group, baseAttrs: merged}
}

func (h *groupedRing) WithGroup(name string) slog.Handler {
	// Nested groups: outer.inner
	newGroup := h.group + "." + name
	return &groupedRing{parent: h.parent, group: newGroup, baseAttrs: h.baseAttrs}
}

