package logfan

import (
	"context"
	"errors"
	"log/slog"
	"sync"
)

// Ring is an in-memory ring-buffer slog.Handler that keeps the most
// recent records up to its configured capacity.
type Ring struct {
	mu       sync.RWMutex
	capacity int
	buf      []slog.Record
	start    int
	count    int
}

// NewRing creates a *Ring with the given capacity.
// Returns an error if capacity <= 0.
func NewRing(capacity int) (*Ring, error) {
	if capacity <= 0 {
		return nil, errors.New("logfan: ring capacity must be positive")
	}
	return &Ring{
		capacity: capacity,
		buf:      make([]slog.Record, capacity),
	}, nil
}

// Enabled reports whether the handler handles records at the given level.
// Ring accepts all levels.
func (r *Ring) Enabled(_ context.Context, _ slog.Level) bool {
	return true
}

// Handle stores the slog.Record in the ring buffer.
func (r *Ring) Handle(_ context.Context, rec slog.Record) error {
	r.mu.Lock()
	defer r.mu.Unlock()

	idx := (r.start + r.count) % r.capacity
	r.buf[idx] = rec.Clone()
	if r.count == r.capacity {
		r.start = (r.start + 1) % r.capacity
	} else {
		r.count++
	}
	return nil
}

// WithAttrs returns a Handler whose attributes consist of attrs followed
// by the attributes of any record handled.
func (r *Ring) WithAttrs(attrs []slog.Attr) slog.Handler {
	return &wrapper{ring: r, attrs: attrs}
}

// WithGroup returns a Handler that starts a group with the given name.
func (r *Ring) WithGroup(name string) slog.Handler {
	return &wrapper{ring: r, group: name}
}

// Records returns the buffered records, oldest first.
// The returned slice is a copy — mutating it does not affect the ring.
func (r *Ring) Records() []slog.Record {
	r.mu.RLock()
	defer r.mu.RUnlock()

	out := make([]slog.Record, r.count)
	for i := 0; i < r.count; i++ {
		idx := (r.start + i) % r.capacity
		out[i] = r.buf[idx].Clone()
	}
	return out
}

// wrapper is a slog.Handler that applies attrs/grouping before delegating
// to the parent (either the Ring or another wrapper), building a chain.
type wrapper struct {
	parent slog.Handler // the next handler in the chain (Ring or another wrapper)
	ring   *Ring        // final Ring sink (only set when this wrapper attaches directly to Ring)
	attrs  []slog.Attr
	group  string
}

// resolveParent returns the parent handler for this wrapper.
// If ring is set, this wrapper attaches directly to Ring; otherwise
// parent must be set.
func (w *wrapper) resolveParent() slog.Handler {
	if w.ring != nil {
		return w.ring
	}
	return w.parent
}

func (w *wrapper) Enabled(ctx context.Context, level slog.Level) bool {
	return w.resolveParent().Enabled(ctx, level)
}

func (w *wrapper) Handle(ctx context.Context, rec slog.Record) error {
	parent := w.resolveParent()

	if w.group != "" {
		// Collect existing record attrs.
		var recAttrs []slog.Attr
		rec.Attrs(func(a slog.Attr) bool {
			recAttrs = append(recAttrs, a)
			return true
		})

		newRec := slog.NewRecord(rec.Time, rec.Level, rec.Message, rec.PC)
		// Wrap everything inside the group.
		groupArgs := make([]any, 0, len(w.attrs)+len(recAttrs))
		for _, a := range w.attrs {
			groupArgs = append(groupArgs, a)
		}
		for _, a := range recAttrs {
			groupArgs = append(groupArgs, a)
		}
		newRec.AddAttrs(slog.Group(w.group, groupArgs...))
		return parent.Handle(ctx, newRec)
	}

	// No group: just prepend attrs.
	if len(w.attrs) > 0 {
		rec.AddAttrs(w.attrs...)
	}
	return parent.Handle(ctx, rec)
}

func (w *wrapper) WithAttrs(attrs []slog.Attr) slog.Handler {
	if w.ring != nil {
		return &wrapper{ring: w.ring, attrs: attrs}
	}
	return &wrapper{parent: w, attrs: attrs}
}

func (w *wrapper) WithGroup(name string) slog.Handler {
	if w.ring != nil {
		return &wrapper{ring: w.ring, group: name}
	}
	return &wrapper{parent: w, group: name}
}

package logfan

import (
	"context"
	"errors"
	"log/slog"
)

// fanHandler delivers every record to all of its handlers.
type fanHandler struct {
	handlers []slog.Handler
}

// New builds a logger that delivers every record to ALL given handlers.
// Returns an error when called with no handlers.
func New(handlers ...slog.Handler) (*slog.Logger, error) {
	if len(handlers) == 0 {
		return nil, errors.New("logfan: at least one handler required")
	}
	return slog.New(&fanHandler{handlers: handlers}), nil
}

func (h *fanHandler) Enabled(ctx context.Context, level slog.Level) bool {
	for _, handler := range h.handlers {
		if handler.Enabled(ctx, level) {
			return true
		}
	}
	return false
}

func (h *fanHandler) Handle(ctx context.Context, rec slog.Record) error {
	for _, handler := range h.handlers {
		// Clone so each handler gets its own copy — a handler may call
		// AddAttrs on the record (as our ring wrappers do).
		if err := handler.Handle(ctx, rec.Clone()); err != nil {
			return err
		}
	}
	return nil
}

func (h *fanHandler) WithAttrs(attrs []slog.Attr) slog.Handler {
	next := make([]slog.Handler, len(h.handlers))
	for i, handler := range h.handlers {
		next[i] = handler.WithAttrs(attrs)
	}
	return &fanHandler{handlers: next}
}

func (h *fanHandler) WithGroup(name string) slog.Handler {
	next := make([]slog.Handler, len(h.handlers))
	for i, handler := range h.handlers {
		next[i] = handler.WithGroup(name)
	}
	return &fanHandler{handlers: next}
}

package logfan

import (
	"context"
	"log/slog"
	"sync"
	"testing"
	"time"
)

func TestNewRing_InvalidCapacity(t *testing.T) {
	tests := []struct {
		name string
		cap  int
	}{
		{"zero", 0},
		{"negative", -1},
		{"negative large", -100},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			r, err := NewRing(tt.cap)
			if err == nil {
				t.Fatal("expected error for invalid capacity")
			}
			if r != nil {
				t.Fatal("expected nil Ring on error")
			}
		})
	}
}

func TestNewRing_ValidCapacity(t *testing.T) {
	r, err := NewRing(5)
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if r == nil {
		t.Fatal("expected non-nil Ring")
	}
	recs := r.Records()
	if len(recs) != 0 {
		t.Fatalf("expected 0 records, got %d", len(recs))
	}
}

func TestRing_Basic(t *testing.T) {
	r, err := NewRing(3)
	if err != nil {
		t.Fatal(err)
	}

	ctx := context.Background()
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	rec1 := slog.NewRecord(now, slog.LevelInfo, "msg1", 0)
	rec2 := slog.NewRecord(now, slog.LevelWarn, "msg2", 0)
	rec3 := slog.NewRecord(now, slog.LevelError, "msg3", 0)

	if err := r.Handle(ctx, rec1); err != nil {
		t.Fatal(err)
	}
	if err := r.Handle(ctx, rec2); err != nil {
		t.Fatal(err)
	}
	if err := r.Handle(ctx, rec3); err != nil {
		t.Fatal(err)
	}

	recs := r.Records()
	if len(recs) != 3 {
		t.Fatalf("expected 3 records, got %d", len(recs))
	}
	if recs[0].Message != "msg1" {
		t.Fatalf("expected msg1, got %s", recs[0].Message)
	}
	if recs[1].Message != "msg2" {
		t.Fatalf("expected msg2, got %s", recs[1].Message)
	}
	if recs[2].Message != "msg3" {
		t.Fatalf("expected msg3, got %s", recs[2].Message)
	}
}

func TestRing_EvictsOldest(t *testing.T) {
	r, err := NewRing(3)
	if err != nil {
		t.Fatal(err)
	}

	ctx := context.Background()
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	for i := range 5 {
		rec := slog.NewRecord(now, slog.LevelInfo, slog.IntValue(i).String(), 0)
		if err := r.Handle(ctx, rec); err != nil {
			t.Fatal(err)
		}
	}

	recs := r.Records()
	if len(recs) != 3 {
		t.Fatalf("expected 3 records, got %d", len(recs))
	}
	// Oldest should be msg "2", "3", "4".
	if recs[0].Message != "2" {
		t.Fatalf("expected oldest to be '2', got %s", recs[0].Message)
	}
	if recs[1].Message != "3" {
		t.Fatalf("expected middle to be '3', got %s", recs[1].Message)
	}
	if recs[2].Message != "4" {
		t.Fatalf("expected newest to be '4', got %s", recs[2].Message)
	}
}

func TestRing_RecordsReturnsCopy(t *testing.T) {
	r, err := NewRing(2)
	if err != nil {
		t.Fatal(err)
	}

	ctx := context.Background()
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	rec := slog.NewRecord(now, slog.LevelInfo, "msg", 0)
	if err := r.Handle(ctx, rec); err != nil {
		t.Fatal(err)
	}

	recs1 := r.Records()
	recs2 := r.Records()

	// Mutate the first returned slice
	recs1[0].Message = "hacked"

	if recs2[0].Message != "msg" {
		t.Fatal("mutating returned Records slice affected the ring buffer")
	}

	// Verify the ring still holds the original
	recs3 := r.Records()
	if recs3[0].Message != "msg" {
		t.Fatal("mutating returned Records slice corrupted internal state")
	}
}

func TestRing_EnabledAlwaysTrue(t *testing.T) {
	r, err := NewRing(1)
	if err != nil {
		t.Fatal(err)
	}
	if !r.Enabled(context.Background(), slog.LevelDebug) {
		t.Fatal("Ring should be enabled for Debug")
	}
	if !r.Enabled(context.Background(), slog.LevelInfo) {
		t.Fatal("Ring should be enabled for Info")
	}
	if !r.Enabled(context.Background(), slog.LevelError) {
		t.Fatal("Ring should be enabled for Error")
	}
}

func TestRing_WithAttrs(t *testing.T) {
	r, err := NewRing(2)
	if err != nil {
		t.Fatal(err)
	}

	ctx := context.Background()
	h := r.WithAttrs([]slog.Attr{slog.String("key1", "val1")})
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	rec := slog.NewRecord(now, slog.LevelInfo, "msg", 0)
	if err := h.Handle(ctx, rec); err != nil {
		t.Fatal(err)
	}

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}

	var found bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "key1" && a.Value.String() == "val1" {
			found = true
			return false
		}
		return true
	})
	if !found {
		t.Fatal("expected key1=val1 attr on record")
	}
}

func TestRing_WithGroup(t *testing.T) {
	r, err := NewRing(2)
	if err != nil {
		t.Fatal(err)
	}

	ctx := context.Background()
	h := r.WithGroup("g")
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	rec := slog.NewRecord(now, slog.LevelInfo, "msg", 0)
	if err := h.Handle(ctx, rec); err != nil {
		t.Fatal(err)
	}

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}

	var found bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "g" && a.Value.Kind() == slog.KindGroup {
			found = true
			return false
		}
		return true
	})
	if !found {
		t.Fatal("expected group 'g' to wrap record attrs")
	}
}

func TestRing_WithAttrsThenGroup(t *testing.T) {
	r, err := NewRing(2)
	if err != nil {
		t.Fatal(err)
	}

	ctx := context.Background()
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	// Chain: WithAttrs(a1) -> WithGroup("g") -> WithAttrs(a2)
	h := r.WithAttrs([]slog.Attr{slog.String("top", "t")})
	h = h.WithGroup("g")
	h = h.WithAttrs([]slog.Attr{slog.String("inner", "i")})

	rec := slog.NewRecord(now, slog.LevelInfo, "msg", 0)
	if err := h.Handle(ctx, rec); err != nil {
		t.Fatal(err)
	}

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}

	// Should have "top" at top level and group "g" containing "inner".
	var topFound, groupFound bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "top" {
			topFound = true
		}
		if a.Key == "g" && a.Value.Kind() == slog.KindGroup {
			groupFound = true
		}
		return true
	})
	if !topFound {
		t.Fatal("expected top-level attr 'top'")
	}
	if !groupFound {
		t.Fatal("expected group 'g'")
	}
}

func TestRing_ConcurrentSafe(t *testing.T) {
	r, err := NewRing(100)
	if err != nil {
		t.Fatal(err)
	}

	ctx := context.Background()
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	var wg sync.WaitGroup
	n := 50

	// Concurrent writes
	for i := range n {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			rec := slog.NewRecord(now, slog.LevelInfo, slog.IntValue(i).String(), 0)
			_ = r.Handle(ctx, rec) //nolint:errcheck
		}(i)
	}

	// Concurrent reads
	for range n {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_ = r.Records() //nolint:errcheck
		}()
	}

	wg.Wait()

	// After all writes, there should be some records
	recs := r.Records()
	if len(recs) == 0 {
		t.Fatal("expected at least some records after concurrent writes")
	}
}

func TestRing_ChainWithGroupThenAttrs(t *testing.T) {
	r, err := NewRing(2)
	if err != nil {
		t.Fatal(err)
	}

	ctx := context.Background()
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	// Chain: WithGroup("g") -> WithAttrs(a)
	h := r.WithGroup("g")
	h = h.WithAttrs([]slog.Attr{slog.String("k", "v")})

	rec := slog.NewRecord(now, slog.LevelInfo, "msg", 0)
	if err := h.Handle(ctx, rec); err != nil {
		t.Fatal(err)
	}

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}

	// Should have group "g" containing "k=v".
	var group *slog.Attr
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "g" && a.Value.Kind() == slog.KindGroup {
			group = &a
			return false
		}
		return true
	})
	if group == nil {
		t.Fatal("expected group 'g'")
	}

	var innerFound bool
	for _, a := range group.Value.Group() {
		if a.Key == "k" {
			innerFound = true
		}
	}
	if !innerFound {
		t.Fatal("expected attr 'k' inside group 'g'")
	}
}

func TestRing_WithAttrsChained(t *testing.T) {
	r, err := NewRing(2)
	if err != nil {
		t.Fatal(err)
	}

	ctx := context.Background()
	now := time.Date(2025, 1, 1, 0, 0, 0, 0, time.UTC)

	h := r.WithAttrs([]slog.Attr{slog.String("a", "1")})
	h = h.WithAttrs([]slog.Attr{slog.String("b", "2")})

	rec := slog.NewRecord(now, slog.LevelInfo, "msg", 0)
	if err := h.Handle(ctx, rec); err != nil {
		t.Fatal(err)
	}

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}

	var aFound, bFound bool
	recs[0].Attrs(func(a slog.Attr) bool {
		if a.Key == "a" {
			aFound = true
		}
		if a.Key == "b" {
			bFound = true
		}
		return true
	})
	if !aFound {
		t.Fatal("expected attr 'a'")
	}
	if !bFound {
		t.Fatal("expected attr 'b'")
	}
}

package logfan

import (
