	if err != nil {
		t.Fatal(err)
	}

	logger = logger.WithGroup("req").With("id", "42")
	logger.Info("request")

	recs := r.Records()
	if len(recs) != 1 {
		t.Fatalf("expected 1 record, got %d", len(recs))
	}

